def get_css(theme: str) -> str:
    if theme == "노른자 크림(추천)":
        from .cream_theme import CREAM_CSS
        return CREAM_CSS
    base = CLASSIC_CSS if theme == "기존 다크·민트" else NORUNJA_CSS
    accent = "#3ce0c5" if theme == "기존 다크·민트" else "#FFD048"
    controls = f"""<style>
    [data-testid='stNumberInput'] input,
    [data-testid='stTimeInput'] input,
    [data-testid='stFileUploader'] section,
    [data-testid='stMultiSelect'] div[data-baseweb='select']>div {{
       background-color: #142538 !important;
       color: #f2f8fd !important;
       border-color: #36566b !important;
       border-radius: 10px !important;
    }}
    [data-testid='stTabs'] button[aria-selected='true'] {{
       border-bottom-color: {accent} !important;
       color: {accent} !important;
    }}
    [data-testid='stTabs'] [data-baseweb='tab-highlight'] {{background: {accent} !important;}}
    </style>"""
    return base + controls
